1	package com.example.starter.wb.service;
2	
3	import com.example.starter.wb.calc.CalcLoadItem;
4	import com.example.starter.wb.calc.WeightBalanceCalculator;
5	import com.example.starter.wb.calc.WeightBalanceResult;
6	import com.example.starter.wb.domain.Aircraft;
7	import com.example.starter.wb.domain.Flight;
8	import com.example.starter.wb.domain.IdempotentRow;
9	import com.example.starter.wb.domain.LateEventRow;
10	import com.example.starter.wb.domain.LoadDetailRow;
11	import com.example.starter.wb.domain.LoadStation;
12	import com.example.starter.wb.domain.LmcLogRow;
13	import com.example.starter.wb.domain.ManifestRow;
14	import com.example.starter.wb.domain.ReviewRow;
15	import com.example.starter.wb.dto.CheckinRequest;
16	import com.example.starter.wb.dto.CloseRequest;
17	import com.example.starter.wb.dto.CreateManifestRequest;
18	import com.example.starter.wb.dto.LateAlert;
19	import com.example.starter.wb.dto.LateCheckinRequest;
20	import com.example.starter.wb.dto.LoadItem;
21	import com.example.starter.wb.dto.LmcRequest;
22	import com.example.starter.wb.dto.ManifestResponse;
23	import com.example.starter.wb.dto.ReviewRequest;
24	import com.example.starter.wb.dto.StageRequest;
25	import com.example.starter.wb.enums.LoadCategory;
26	import com.example.starter.wb.enums.ManifestStatus;
27	import com.example.starter.wb.enums.ReviewRole;
28	import com.example.starter.wb.exception.BadRequestException;
29	import com.example.starter.wb.exception.ConflictException;
30	import com.example.starter.wb.exception.NotFoundException;
31	import com.example.starter.wb.exception.UnprocessableException;
32	import com.example.starter.wb.repo.IdempotencyStore;
33	import com.example.starter.wb.repo.WeightBalanceRepository;
34	import com.example.starter.wb.support.FingerprintUtil;
35	import com.fasterxml.jackson.databind.ObjectMapper;
36	import org.slf4j.Logger;
37	import org.slf4j.LoggerFactory;
38	import org.springframework.dao.DuplicateKeyException;
39	import org.springframework.stereotype.Service;
40	import org.springframework.transaction.annotation.Transactional;
41	
42	import java.math.BigDecimal;
43	import java.time.Clock;
44	import java.time.LocalDateTime;
45	import java.util.ArrayList;
46	import java.util.LinkedHashMap;
47	import java.util.List;
48	import java.util.Map;
49	import java.util.Optional;
50	
51	/**
52	 * 载重平衡舱单核心服务。
53	 *
54	 * <p>状态机：预配 PRELIMINARY → 值机 CHECKIN → 装载确认 LOADED →
55	 * 双岗复核 REVIEWED（冻结）→ 放行关闭 CLOSED（终态）；LMC 超限重打产生新版本（SUPERSEDED 链）。
56	 *
57	 * <p>所有写操作以 requestId 幂等：SHA-256 指纹覆盖 requestId 与全部业务字段；
58	 * 同键同参回放首次结果，同键异参 409。加油量变更与重心重算在同一事务同一 UPDATE 内完成。
59	 */
60	@Service
61	public class WeightBalanceServiceImpl implements WeightBalanceService {
62	
63	    private static final Logger log = LoggerFactory.getLogger(WeightBalanceServiceImpl.class);
64	
65	    /** LMC 限额：恰达含。 */
66	    static final int LMC_PAX_LIMIT = 5;
67	    static final BigDecimal LMC_WEIGHT_LIMIT = new BigDecimal("500.00");
68	
69	    private final WeightBalanceRepository repo;
70	    private final IdempotencyStore idempotencyStore;
71	    private final ObjectMapper objectMapper;
72	    private final Clock clock;
73	
74	    public WeightBalanceServiceImpl(WeightBalanceRepository repo, IdempotencyStore idempotencyStore,
75	                                    ObjectMapper objectMapper, Clock clock) {
76	        this.repo = repo;
77	        this.idempotencyStore = idempotencyStore;
78	        this.objectMapper = objectMapper;
79	        this.clock = clock;
80	    }
81	
82	    // ------------------------------------------------------------------ 预配
83	
84	    @Override
85	    @Transactional
86	    public ManifestResponse createManifest(CreateManifestRequest request) {
87	        return withIdempotency(request.requestId(), request, 201, () -> {
88	            Flight flight = requireFlight(request.flightId());
89	            Aircraft ac = requireAircraft(flight.aircraftId());
90	            if (repo.findActiveByFlightId(flight.id()).isPresent()) {
91	                throw new ConflictException("航班 " + flight.id() + " 已存在有效舱单版本");
92	            }
93	            List<LoadDetailRow> details = toDetails(request.items(), ac, 0);
94	            WeightBalanceResult wb = WeightBalanceCalculator.calculate(ac, toCalcItems(details, ac), request.fuelKg());
95	            ensureWithinLimits(wb);
96	
97	            LocalDateTime now = LocalDateTime.now(clock);
98	            ManifestRow row = new ManifestRow(
99	                    null, flight.id(), 1, null, request.requestId(),
100	                    fingerprint(request.requestId(), request),
101	                    ManifestStatus.PRELIMINARY.name(),
102	                    wb.passengerCount(), wb.payloadKg(), wb.fuelKg(), wb.zfwKg(), wb.towKg(),
103	                    wb.cgZfwPct(), wb.cgTowPct(), true, 0, BigDecimal.ZERO.setScale(2),
104	                    flight.id(), request.createdBy(), now, now, null);
105	            long id = insertManifestActive(row);
106	            repo.insertDetails(id, withManifestId(details, id));
107	            return toResponse(repo.findManifestById(id).orElseThrow());
108	        });
109	    }
110	
111	    // ------------------------------------------------------------------ 值机
112	
113	    @Override
114	    @Transactional
115	    public ManifestResponse checkin(long flightId, CheckinRequest request) {
116	        return withIdempotency(request.requestId(), request, 200, () -> {
117	            ActiveCtx ctx = requireActive(flightId);
118	            requireStatus(ctx.row(), ManifestStatus.PRELIMINARY, "值机");
119	            Aircraft ac = ctx.aircraft();
120	            BigDecimal fuel = request.fuelKg() != null ? request.fuelKg() : ctx.row().fuelKg();
121	            List<LoadDetailRow> details = toDetails(request.items(), ac, 0);
122	            WeightBalanceResult wb = WeightBalanceCalculator.calculate(ac, toCalcItems(details, ac), fuel);
123	            ensureWithinLimits(wb);
124	
125	            long id = ctx.row().id();
126	            repo.deleteDetailsByManifest(id);
127	            repo.insertDetails(id, withManifestId(details, id));
128	            LocalDateTime now = LocalDateTime.now(clock);
129	            repo.updateComputed(copyRow(ctx.row(), wb, ManifestStatus.CHECKIN.name(),
130	                    ctx.row().lmcPaxDelta(), ctx.row().lmcWeightDelta(), now));
131	            return toResponse(repo.findManifestById(id).orElseThrow());
132	        });
133	    }
134	
135	    // ------------------------------------------------------------- 装载确认
136	
137	    @Override
138	    @Transactional
139	    public ManifestResponse confirmLoad(long flightId, StageRequest request) {
140	        return withIdempotency(request.requestId(), request, 200, () -> {
141	            ActiveCtx ctx = requireActive(flightId);
142	            requireStatus(ctx.row(), ManifestStatus.CHECKIN, "装载确认");
143	            repo.updateStatus(ctx.row().id(), ManifestStatus.LOADED.name(), null);
144	            return toResponse(repo.findManifestById(ctx.row().id()).orElseThrow());
145	        });
146	    }
147	
148	    // ----------------------------------------------------------------- LMC
149	
150	    @Override
151	    @Transactional
152	    public ManifestResponse applyLmc(long flightId, LmcRequest request) {
153	        return withIdempotency(request.requestId(), request, 200, () -> {
154	            ActiveCtx ctx = requireActive(flightId);
155	            ManifestRow row = ctx.row();
156	            if (ManifestStatus.REVIEWED.name().equals(row.status())
157	                    || ManifestStatus.CLOSED.name().equals(row.status())) {
158	                throw new ConflictException("舱单已" + (ManifestStatus.CLOSED.name().equals(row.status()) ? "放行关闭" : "复核冻结")
159	                        + "，不能直接 LMC；关闭后变化走迟到值机登记");
160	            }
161	            if (ManifestStatus.PRELIMINARY.name().equals(row.status())) {
162	                throw new ConflictException("预配阶段请使用值机全量更新，不能 LMC");
163	            }
164	            Aircraft ac = ctx.aircraft();
165	            validateLmcStations(ac, request);
166	
167	            int newPaxDelta = row.lmcPaxDelta() + request.passengerDelta();
168	            BigDecimal newWeightDelta = row.lmcWeightDelta().add(request.weightDeltaKg());
169	            boolean withinLmc = Math.abs(newPaxDelta) <= LMC_PAX_LIMIT
170	                    && newWeightDelta.abs().compareTo(LMC_WEIGHT_LIMIT) <= 0;
171	
172	            // 本版既有明细 + 本次增量明细；加油量变更同步参与重心重算（同一事务）。
173	            List<LoadDetailRow> existing = repo.findDetails(row.id());
174	            int nextSeq = existing.stream().mapToInt(LoadDetailRow::seqNo).max().orElse(-1) + 1;
175	            List<LoadDetailRow> deltaRows = lmcDeltaDetails(request, ac, nextSeq);
176	            List<LoadDetailRow> merged = new ArrayList<>(existing);
177	            merged.addAll(deltaRows);
178	            // 退载不得使站位在机人数或货物重量为负。
179	            for (CalcLoadItem item : toCalcItems(merged, ac)) {
180	                if (item.isPassenger() && item.pieces() < 0) {
181	                    throw new UnprocessableException("LMC 后站位 " + item.stationCode() + " 旅客人数为负，退载人数超过在机人数");
182	                }
183	                if (item.weightKg().signum() < 0) {
184	                    throw new UnprocessableException("LMC 后站位 " + item.stationCode()
185	                            + " 的 " + item.category() + " 重量为负，退载重量超过在机重量");
186	                }
187	            }
188	            BigDecimal newFuel = row.fuelKg().add(request.fuelDeltaKg());
189	            WeightBalanceResult wb = WeightBalanceCalculator.calculate(ac, toCalcItems(merged, ac), newFuel);
190	            ensureWithinLimits(wb);
191	
192	            LocalDateTime now = LocalDateTime.now(clock);
193	            if (withinLmc) {
194	                // 限内：同一版本修订，油量与重心在同一 UPDATE 内落库。
195	                long lmcId = repo.insertLmcLog(new LmcLogRow(
196	                        null, row.id(), request.requestId(), request.passengerDelta(),
197	                        request.weightDeltaKg(), request.fuelDeltaKg(), newPaxDelta, newWeightDelta,
198	                        true, null, now));
199	                repo.insertDetails(row.id(), withManifestId(deltaRows, row.id()));
200	                repo.updateComputed(copyRow(row, wb, row.status(), newPaxDelta, newWeightDelta, now));
201	                return toResponse(repo.findManifestById(row.id()).orElseThrow());
202	            }
203	
204	            // 超限：必须重打舱单——旧版作废、生成新版本链；新版本需重新双岗复核。
205	            log.warn("LMC 超过 ±{} 人/±{}kg 限额（累计 {} 人, {}kg），航班 {} 重打新版本",
206	                    LMC_PAX_LIMIT, LMC_WEIGHT_LIMIT, newPaxDelta, newWeightDelta, flightId);
207	            long lmcId = repo.insertLmcLog(new LmcLogRow(
208	                    null, row.id(), request.requestId(), request.passengerDelta(),
209	                    request.weightDeltaKg(), request.fuelDeltaKg(), newPaxDelta, newWeightDelta,
210	                    false, null, now));
211	            int newVersionNo = row.versionNo() + 1;
212	            String newStatus = ManifestStatus.LOADED.name().equals(row.status())
213	                    ? ManifestStatus.LOADED.name() : ManifestStatus.CHECKIN.name();
214	            ManifestRow newRow = new ManifestRow(
215	                    null, flightId, newVersionNo, row.id(), request.requestId(),
216	                    fingerprint(request.requestId(), request),
217	                    newStatus, wb.passengerCount(), wb.payloadKg(), wb.fuelKg(), wb.zfwKg(), wb.towKg(),
218	                    wb.cgZfwPct(), wb.cgTowPct(), true, 0, BigDecimal.ZERO.setScale(2),
219	                    flightId, request.operator(), now, now, null);
220	            long newId = reprintActive(row, newRow);
221	            // 新版本明细 = 旧版全部明细（含历次限内增量）+ 本次触发重打的增量，保证可复算。
222	            repo.insertDetails(newId, withManifestId(merged, newId));
223	            repo.linkLmcNewVersion(lmcId, newId);
224	            return toResponse(repo.findManifestById(newId).orElseThrow());
225	        });
226	    }
227	
228	    // ----------------------------------------------------------------- 双岗
229	
230	    @Override
231	    @Transactional
232	    public ManifestResponse review(long flightId, ReviewRequest request) {
233	        return withIdempotency(request.requestId(), request, 200, () -> {
234	            ActiveCtx ctx = requireActive(flightId);
235	            ManifestRow row = ctx.row();
236	            ReviewRole role = parseRole(request.role());
237	            if (!ManifestStatus.LOADED.name().equals(row.status())
238	                    && !ManifestStatus.REVIEWED.name().equals(row.status())) {
239	                throw new ConflictException("仅装载确认后的舱单可提交复核，当前状态 " + row.status());
240	            }
241	            List<ReviewRow> existing = repo.findReviews(row.id());
242	            Optional<ReviewRow> sameRole = existing.stream()
243	                    .filter(r -> r.roleCode().equals(role.name())).findFirst();
244	            if (sameRole.isPresent()) {
245	                throw new ConflictException("岗位 " + role.name() + " 已由 " + sameRole.get().reviewer() + " 签字，唯一有效");
246	            }
247	            if (existing.stream().anyMatch(r -> r.reviewer().equals(request.reviewer()))) {
248	                throw new UnprocessableException("双岗复核须由两名不同人员完成，" + request.reviewer() + " 已签字");
249	            }
250	            LocalDateTime now = LocalDateTime.now(clock);
251	            try {
252	                repo.insertReview(new ReviewRow(null, row.id(), request.requestId(),
253	                        fingerprint(request.requestId(), request), role.name(), request.reviewer(), now));
254	            } catch (DuplicateKeyException e) {
255	                throw new ConflictException("岗位 " + role.name() + " 并发签字冲突：每岗位唯一一笔生效");
256	            }
257	
258	            List<ReviewRow> after = repo.findReviews(row.id());
259	            if (after.size() == ReviewRole.values().length) {
260	                // 两个不同岗位均签字：复核通过，舱单冻结。
261	                repo.updateStatus(row.id(), ManifestStatus.REVIEWED.name(), null);
262	            }
263	            return toResponse(repo.findManifestById(row.id()).orElseThrow());
264	        });
265	    }
266	
267	    // ----------------------------------------------------------------- 关闭
268	
269	    @Override
270	    @Transactional
271	    public ManifestResponse close(long flightId, CloseRequest request) {
272	        return withIdempotency(request.requestId(), request, 200, () -> {
273	            ActiveCtx ctx = requireActive(flightId);
274	            ManifestRow row = ctx.row();
275	            if (ManifestStatus.CLOSED.name().equals(row.status())) {
276	                // 终态：重复关闭幂等成功。
277	                return toResponse(row);
278	            }
279	            if (!ManifestStatus.REVIEWED.name().equals(row.status())) {
280	                throw new ConflictException("双岗复核通过后方可放行关闭，当前状态 " + row.status());
281	            }
282	            LocalDateTime now = LocalDateTime.now(clock);
283	            repo.updateStatus(row.id(), ManifestStatus.CLOSED.name(), now);
284	            return toResponse(repo.findManifestById(row.id()).orElseThrow());
285	        });
286	    }
287	
288	    // ------------------------------------------------------------- 迟到值机
289	
290	    @Override
291	    @Transactional
292	    public ManifestResponse recordLateCheckin(long flightId, LateCheckinRequest request) {
293	        return withIdempotency(request.requestId(), request, 200, () -> {
294	            ActiveCtx ctx = requireActive(flightId);
295	            ManifestRow row = ctx.row();
296	            if (!ManifestStatus.CLOSED.name().equals(row.status())) {
297	                throw new ConflictException("舱单未关闭，迟到值机登记仅在放行关闭后受理，当前状态 " + row.status());
298	            }
299	            LocalDateTime now = LocalDateTime.now(clock);
300	            repo.insertLateEvent(new LateEventRow(
301	                    null, flightId, row.id(), request.passengerCount(), request.weightKg(),
302	                    safeJson(request), true, now));
303	            log.warn("ALERT 航班 {} 关闭后收到迟到值机变化：+{} 人 +{}kg，舱单 {} 不再修改",
304	                    flightId, request.passengerCount(), request.weightKg(), row.id());
305	            return toResponse(repo.findManifestById(row.id()).orElseThrow());
306	        });
307	    }
308	
309	    @Override
310	    @Transactional(readOnly = true)
311	    public ManifestResponse getActive(long flightId) {
312	        return toResponse(requireActive(flightId).row());
313	    }
314	
315	    @Override
316	    @Transactional(readOnly = true)
317	    public List<ManifestResponse> listVersions(long flightId) {
318	        requireFlight(flightId);
319	        return repo.findVersionsByFlightId(flightId).stream().map(this::toResponse).toList();
320	    }
321	
322	    // ================================================================ 内部
323	
324	    private record ActiveCtx(ManifestRow row, Aircraft aircraft, Flight flight) {
325	    }
326	
327	    private ActiveCtx requireActive(long flightId) {
328	        Flight flight = requireFlight(flightId);
329	        Aircraft ac = requireAircraft(flight.aircraftId());
330	        ManifestRow row = repo.findActiveByFlightIdForUpdate(flightId)
331	                .orElseThrow(() -> new NotFoundException("航班 " + flightId + " 不存在有效舱单版本"));
332	        return new ActiveCtx(row, ac, flight);
333	    }
334	
335	    private Flight requireFlight(long flightId) {
336	        Flight flight = repo.findFlightById(flightId);
337	        if (flight == null) {
338	            throw new NotFoundException("航班 " + flightId + " 不存在");
339	        }
340	        return flight;
341	    }
342	
343	    private Aircraft requireAircraft(long aircraftId) {
344	        Aircraft ac = repo.findAircraftById(aircraftId);
345	        if (ac == null) {
346	            throw new NotFoundException("飞机 " + aircraftId + " 不存在");
347	        }
348	        return ac;
349	    }
350	
351	    private static void requireStatus(ManifestRow row, ManifestStatus expected, String action) {
352	        if (!expected.name().equals(row.status())) {
353	            throw new ConflictException(action + "要求舱单处于 " + expected + "，当前状态 " + row.status());
354	        }
355	    }
356	
357	    private static void ensureWithinLimits(WeightBalanceResult wb) {
358	        if (!wb.withinLimits()) {
359	            throw new UnprocessableException("载重平衡超出限制：" + String.join("；", wb.violations()));
360	        }
361	    }
362	
363	    private ReviewRole parseRole(String role) {
364	        try {
365	            return ReviewRole.valueOf(role);
366	        } catch (IllegalArgumentException e) {
367	            throw new BadRequestException("未知复核岗位 " + role + "，允许 LOAD_CONTROLLER/FLIGHT_DISPATCHER");
368	        }
369	    }
370	
371	    private void validateLmcStations(Aircraft ac, LmcRequest request) {
372	        stationArm(ac, request.paxStationCode());
373	        stationArm(ac, request.weightStationCode());
374	        try {
375	            LoadCategory cat = LoadCategory.valueOf(request.weightCategory());
376	            if (cat == LoadCategory.PASSENGER) {
377	                throw new BadRequestException("LMC 重量增量类别不能为 PASSENGER，旅客变化使用 passengerDelta");
378	            }
379	        } catch (IllegalArgumentException e) {
380	            throw new BadRequestException("未知业载类别 " + request.weightCategory());
381	        }
382	    }
383	
384	    /** 将 DTO 明细逐条转为持久化明细；totalWeightKg = pieces * unitWeightKg 严格成立。 */
385	    private List<LoadDetailRow> toDetails(List<LoadItem> items, Aircraft ac, int seqStart) {
386	        List<LoadDetailRow> rows = new ArrayList<>();
387	        int seq = seqStart;
388	        for (LoadItem item : items) {
389	            LoadCategory cat = parseCategory(item.category());
390	            stationArm(ac, item.stationCode());
391	            if (item.unitWeightKg() == null || item.unitWeightKg().signum() < 0 || item.pieces() < 0) {
392	                throw new BadRequestException("件数不得为负，单位重量不能为空或负数");
393	            }
394	            BigDecimal total = item.unitWeightKg().multiply(BigDecimal.valueOf(item.pieces()))
395	                    .setScale(2, java.math.RoundingMode.HALF_UP);
396	            rows.add(new LoadDetailRow(null, 0, cat.name(), item.stationCode(),
397	                    item.pieces(), item.unitWeightKg(), total, seq++));
398	        }
399	        return rows;
400	    }
401	
402	    /** LMC 增量明细：旅客按人*单重，货物以 1 件承载增量重量，total=pieces*unit 恒成立。 */
403	    private List<LoadDetailRow> lmcDeltaDetails(LmcRequest req, Aircraft ac, int seqStart) {
404	        List<LoadDetailRow> rows = new ArrayList<>();
405	        int seq = seqStart;
406	        if (req.passengerDelta() != 0) {
407	            BigDecimal w = req.paxUnitWeightKg().multiply(BigDecimal.valueOf(req.passengerDelta())).setScale(2);
408	            rows.add(new LoadDetailRow(null, 0, LoadCategory.PASSENGER.name(),
409	                    req.paxStationCode(), req.passengerDelta(), req.paxUnitWeightKg(), w, seq++));
410	        }
411	        if (req.weightDeltaKg().signum() != 0) {
412	            rows.add(new LoadDetailRow(null, 0, LoadCategory.valueOf(req.weightCategory()).name(),
413	                    req.weightStationCode(), 1, req.weightDeltaKg().setScale(2),
414	                    req.weightDeltaKg().setScale(2), seq++));
415	        }
416	        return rows;
417	    }
418	
419	    private LoadCategory parseCategory(String category) {
420	        try {
421	            return LoadCategory.valueOf(category);
422	        } catch (IllegalArgumentException e) {
423	            throw new BadRequestException("未知业载类别 " + category);
424	        }
425	    }
426	
427	    private static BigDecimal stationArm(Aircraft ac, String stationCode) {
428	        return ac.stations().stream()
429	                .filter(s -> s.stationCode().equals(stationCode))
430	                .map(LoadStation::arm)
431	                .findFirst()
432	                .orElseThrow(() -> new BadRequestException("飞机 " + ac.tailNo() + " 不存在站位 " + stationCode));
433	    }
434	
435	    private List<CalcLoadItem> toCalcItems(List<LoadDetailRow> details, Aircraft ac) {
436	        // 相同（类别,站位）多行（LMC 增量链）在计算时按总重聚合，力臂取站位主数据。
437	        Map<String, BigDecimal> weightByKey = new LinkedHashMap<>();
438	        Map<String, Integer> piecesByKey = new LinkedHashMap<>();
439	        for (LoadDetailRow d : details) {
440	            String key = d.category() + "|" + d.stationCode();
441	            weightByKey.merge(key, d.totalWeightKg(), BigDecimal::add);
442	            piecesByKey.merge(key, d.pieces(), Integer::sum);
443	        }
444	        List<CalcLoadItem> items = new ArrayList<>();
445	        weightByKey.forEach((key, weight) -> {
446	            String[] parts = key.split("\\|", 2);
447	            items.add(new CalcLoadItem(parts[0], parts[1], piecesByKey.get(key),
448	                    weight.setScale(2, java.math.RoundingMode.HALF_UP), stationArm(ac, parts[1])));
449	        });
450	        return items;
451	    }
452	
453	    private List<LoadDetailRow> withManifestId(List<LoadDetailRow> rows, long manifestId) {
454	        return rows.stream()
455	                .map(r -> new LoadDetailRow(r.id(), manifestId, r.category(), r.stationCode(),
456	                        r.pieces(), r.unitWeightKg(), r.totalWeightKg(), r.seqNo()))
457	                .toList();
458	    }
459	
460	    private ManifestRow copyRow(ManifestRow r, WeightBalanceResult wb, String status,
461	                                int lmcPax, BigDecimal lmcWeight, LocalDateTime now) {
462	        return new ManifestRow(r.id(), r.flightId(), r.versionNo(), r.parentVersionId(), r.requestId(),
463	                r.fingerprint(), status, wb.passengerCount(), wb.payloadKg(), wb.fuelKg(), wb.zfwKg(),
464	                wb.towKg(), wb.cgZfwPct(), wb.cgTowPct(), true, lmcPax, lmcWeight,
465	                r.activeFlag(), r.createdBy(), r.createdAt(), now, r.closedAt());
466	    }
467	
468	    private long insertManifestActive(ManifestRow row) {
469	        try {
470	            return repo.insertManifest(row);
471	        } catch (DuplicateKeyException e) {
472	            Optional<ManifestRow> active = repo.findActiveByFlightId(row.flightId());
473	            if (active.isPresent()) {
474	                throw new ConflictException("航班 " + row.flightId() + " 已存在有效舱单版本（并发创建唯一成功）");
475	            }
476	            throw new ConflictException("requestId 已用于不同请求");
477	        }
478	    }
479	
480	    /** 旧版作废后插入新版本；(flight_id, active_flag) 唯一约束保证同时刻仅一个有效版本。 */
481	    private long reprintActive(ManifestRow oldRow, ManifestRow newRow) {
482	        repo.supersede(oldRow.id());
483	        try {
484	            return repo.insertManifest(newRow);
485	        } catch (DuplicateKeyException e) {
486	            throw new ConflictException("重打新版本冲突，航班仅允许一个有效版本");
487	        }
488	    }
489	
490	    private String fingerprint(String requestId, Object payload) {
491	        return FingerprintUtil.sha256(requestId, payload, objectMapper);
492	    }
493	
494	    /**
495	     * requestId 幂等包装：先查幂等表，同键同参回放首次结果（成功或失败），同键异参 409；
496	     * 首次结果（含业务失败）以独立事务落快照，业务事务回滚不影响幂等记录。
497	     */
498	    private ManifestResponse withIdempotency(String requestId, Object payload, int successStatus,
499	                                             java.util.function.Supplier<ManifestResponse> action) {
500	        String fp = fingerprint(requestId, payload);
501	        Optional<IdempotentRow> existing = idempotencyStore.find(requestId);
502	        if (existing.isPresent()) {
503	            return replay(existing.get(), fp, requestId);
504	        }
505	        ManifestResponse response;
506	        try {
507	            response = action.get();
508	        } catch (DuplicateKeyException dke) {
509	            // 并发同键：唯一约束决胜，转为回放或冲突。
510	            Optional<IdempotentRow> raced = idempotencyStore.find(requestId);
511	            if (raced.isPresent() && raced.get().fingerprint().equals(fp)) {
512	                return replay(raced.get(), fp, requestId);
513	            }
514	            ConflictException ce = new ConflictException(
515	                    "相同请求并发处理，唯一一笔生效，requestId=" + requestId);
516	            rememberFailure(requestId, fp, ce);
517	            throw ce;
518	        } catch (RuntimeException ex) {
519	            rememberFailure(requestId, fp, ex);
520	            throw ex;
521	        }
522	        remember(requestId, fp, successStatus, safeJson(response));
523	        return response;
524	    }
525	
526	    private void rememberFailure(String requestId, String fp, RuntimeException ex) {
527	        int status = httpStatusOf(ex);
528	        if (status == 0) {
529	            // 非可预期业务错误，不缓存
530	            return;
531	        }
532	        String body = safeJson(Map.of("error", errorName(status), "message", String.valueOf(ex.getMessage())));
533	        remember(requestId, fp, status, body);
534	    }
535	
536	    private void remember(String requestId, String fp, int status, String body) {
537	        try {
538	            idempotencyStore.insert(new IdempotentRow(requestId, fp, status, body,
539	                    LocalDateTime.now(clock)));
540	        } catch (DuplicateKeyException e) {
541	            // 并发下另一线程已记录，交由调用前的查询逻辑在重试时回放。
542	        }
543	    }
544	
545	    private ManifestResponse replay(IdempotentRow row, String currentFp, String requestId) {
546	        if (!row.fingerprint().equals(currentFp)) {
547	            throw new ConflictException("requestId " + requestId
548	                    + " 已用于不同业务参数（指纹不一致），拒绝产生新版本");
549	        }
550	        if (row.httpStatus() == 200 || row.httpStatus() == 201) {
551	            try {
552	                return objectMapper.readValue(row.resultJson(), ManifestResponse.class);
553	            } catch (Exception e) {
554	                throw new IllegalStateException("回放首次结果失败", e);
555	            }
556	        }
557	        String message = row.resultJson();
558	        try {
559	            message = objectMapper.readTree(row.resultJson()).path("message").asText(row.resultJson());
560	        } catch (Exception ignored) {
561	            // 保留原文
562	        }
563	        throw replayException(row.httpStatus(), message);
564	    }
565	
566	    private static int httpStatusOf(RuntimeException ex) {
567	        if (ex instanceof NotFoundException) {
568	            return 404;
569	        }
570	        if (ex instanceof ConflictException) {
571	            return 409;
572	        }
573	        if (ex instanceof UnprocessableException) {
574	            return 422;
575	        }
576	        if (ex instanceof BadRequestException) {
577	            return 400;
578	        }
579	        return 0;
580	    }
581	
582	    private static String errorName(int status) {
583	        return switch (status) {
584	            case 400 -> "Bad Request";
585	            case 404 -> "Not Found";
586	            case 409 -> "Conflict";
587	            case 422 -> "Unprocessable Entity";
588	            default -> "Error";
589	        };
590	    }
591	
592	    private static RuntimeException replayException(int status, String message) {
593	        return switch (status) {
594	            case 400 -> new BadRequestException(message);
595	            case 404 -> new NotFoundException(message);
596	            case 409 -> new ConflictException(message);
597	            case 422 -> new UnprocessableException(message);
598	            default -> new UnprocessableException(message);
599	        };
600	    }
601	
602	    private String safeJson(Object value) {
603	        try {
604	            return objectMapper.writeValueAsString(value);
605	        } catch (Exception e) {
606	            throw new IllegalStateException("响应序列化失败", e);
607	        }
608	    }
609	
610	    /** 组装响应；重量/重心由明细与油量重新计算，验证可复算，violations 随之得出。 */
611	    private ManifestResponse toResponse(ManifestRow row) {
612	        Flight flight = requireFlight(row.flightId());
613	        Aircraft ac = requireAircraft(flight.aircraftId());
614	        List<LoadDetailRow> details = repo.findDetails(row.id());
615	        WeightBalanceResult recomputed = WeightBalanceCalculator.calculate(ac, toCalcItems(details, ac), row.fuelKg());
616	        List<ReviewRow> reviews = repo.findReviews(row.id());
617	        List<LateEventRow> lateEvents = repo.findLateEvents(row.flightId());
618	        Long supersededBy = null;
619	        if (ManifestStatus.SUPERSEDED.name().equals(row.status())) {
620	            supersededBy = repo.findVersionsByFlightId(row.flightId()).stream()
621	                    .filter(v -> row.id().equals(v.parentVersionId()))
622	                    .map(ManifestRow::id)
623	                    .findFirst().orElse(null);
624	        }
625	        boolean frozen = ManifestStatus.REVIEWED.name().equals(row.status())
626	                || ManifestStatus.CLOSED.name().equals(row.status())
627	                || ManifestStatus.SUPERSEDED.name().equals(row.status());
628	        List<LateAlert> alerts = lateEvents.stream()
629	                .map(e -> new LateAlert(e.id(), e.passengerCount(), e.weightKg(),
630	                        e.payloadJson(), e.alerted(), e.createdAt()))
631	                .toList();
632	        List<String> roles = reviews.stream().map(ReviewRow::roleCode).toList();
633	        return new ManifestResponse(
634	                row.id(), row.flightId(), row.versionNo(), row.parentVersionId(), row.requestId(),
635	                row.status(), recomputed.passengerCount(), recomputed.payloadKg(), recomputed.fuelKg(),
636	                recomputed.zfwKg(), recomputed.towKg(), recomputed.cgZfwPct(), recomputed.cgTowPct(),
637	                recomputed.withinLimits(), recomputed.violations(),
638	                row.lmcPaxDelta(), row.lmcWeightDelta(),
639	                Math.abs(row.lmcPaxDelta()) <= LMC_PAX_LIMIT
640	                        && row.lmcWeightDelta().abs().compareTo(LMC_WEIGHT_LIMIT) <= 0,
641	                supersededBy, details, roles, frozen, row.closedAt(), alerts);
642	    }
643	}
