50	    @Test
51	    void fullHttpFlowWithBoundaryWeightsAndReviewThenClose() throws Exception {
52	        String rid = UUID.randomUUID().toString();
53	        // 预配：业载恰 15000kg、ZFW 重心恰 14%MAC、TOW 重心恰 15%MAC
54	        rest().perform(post("/api/flights/1/loadsheet")
55	                        .contentType(MediaType.APPLICATION_JSON).content(exactPayloadCreateBody(rid)))
56	                .andExpect(status().isCreated())
57	                .andExpect(jsonPath("$.status").value("PRELIMINARY"))
58	                .andExpect(jsonPath("$.payloadKg").value(15000.00))
59	                .andExpect(jsonPath("$.cgZfwPct").value(14.0000))
60	                .andExpect(jsonPath("$.cgTowPct").value(15.0000))
61	                .andExpect(jsonPath("$.withinLimits").value(true));
62	
63	        // 同键同参回放首次结果（不产生新版本）
64	        rest().perform(post("/api/flights/1/loadsheet")
65	                        .contentType(MediaType.APPLICATION_JSON).content(exactPayloadCreateBody(rid)))
66	                .andExpect(status().isCreated())
67	                .andExpect(jsonPath("$.versionNo").value(1));
68	
