1	package com.example.starter.wb.calc;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	
6	/**
7	 * 重心包线判定：以（重量 kg，%MAC）为坐标的凸/凹多边形，
8	 * 采用射线法判定点是否在内部；恰在边界（顶点或边上）判定为合法。
9	 */
10	public final class EnvelopeChecker {
11	
12	    /** 边界判定容差，吸收四舍五入误差，不改变“恰等合法”的语义。 */
13	    private static final BigDecimal EPS = new BigDecimal("0.000001");
14	
15	    private EnvelopeChecker() {
16	    }
17	
18	    /**
19	     * @param polygon 按顺序排列的包线顶点（重量，%MAC）
20	     * @param weight  待判定重量
21	     * @param macPct  待判定重心 %MAC
22	     * @return true 表示在包线内或恰在边界
23	     */
24	    public static boolean contains(List<EnvelopeVertex> polygon, BigDecimal weight, BigDecimal macPct) {
25	        if (polygon == null || polygon.size() < 3) {
26	            return false;
27	        }
28	        boolean inside = false;
29	        int n = polygon.size();
30	        for (int i = 0, j = n - 1; i < n; j = i++) {
