/**
 * 载重平衡持久化边界。
 */
public interface WeightBalanceRepository {

    Aircraft findAircraftById(long id);

    Flight findFlightById(long id);

    /** 同一航班同时刻唯一有效版本：active_flag = flight_id。 */
    Optional<ManifestRow> findActiveByFlightId(long flightId);

