13	/**
14	 * 载重平衡计算：合成机型 B-TEST，验证业载恰等上限、重心恰包线边界、加油联动重心与超限分支。
15	 */
16	class WeightBalanceCalculatorTest {
17	
18	    private static final Aircraft AC = new Aircraft(
19	            1, "B-TEST", "SYN-J21", 40000, new BigDecimal("700.00"), 55000, 65000, 60000,
20	            new BigDecimal("625.00"), new BigDecimal("250.00"), new BigDecimal("690.00"),
21	            List.of(
22	                    new EnvelopePoint(40000, new BigDecimal("14.0000")),
23	                    new EnvelopePoint(55000, new BigDecimal("14.0000")),
24	                    new EnvelopePoint(65000, new BigDecimal("16.0000")),
25	                    new EnvelopePoint(65000, new BigDecimal("30.0000")),
26	                    new EnvelopePoint(55000, new BigDecimal("32.0000")),
27	                    new EnvelopePoint(40000, new BigDecimal("32.0000"))),
28	            List.of(
29	                    new LoadStation("PAX_F", new BigDecimal("600.00"), "前舱旅客区"),
30	                    new LoadStation("PAX_E", new BigDecimal("760.00"), "后舱旅客区"),
31	                    new LoadStation("CARGO_F", new BigDecimal("500.00"), "前货舱货物"),
32	                    new LoadStation("MAIL_A", new BigDecimal("800.00"), "后货舱邮件")));
33	
34	    /** 100 人 @80kg@600in = 8000kg；7000kg 货 @500in；业载恰为 15000 = MZFW-OEW。 */
35	    private List<CalcLoadItem> exactPayloadItems(int cargoKg) {
36	        return List.of(
37	                new CalcLoadItem("PASSENGER", "PAX_F", 100, new BigDecimal("8000.00"), new BigDecimal("600.00")),
38	                new CalcLoadItem("CARGO", "CARGO_F", 7, new BigDecimal(cargoKg + ".00"), new BigDecimal("500.00")));
39	    }
40	
41	    @Test
42	    void payloadExactlyAtLimitAndZfwCgExactlyOnVertexAreLegal() {
43	        WeightBalanceResult r = WeightBalanceCalculator.calculate(AC, exactPayloadItems(7000), BigDecimal.ZERO);
44	        assertThat(r.payloadKg()).isEqualByComparingTo("15000.00");
45	        assertThat(r.zfwKg()).isEqualByComparingTo("55000");
46	        assertThat(r.cgZfwPct()).isEqualByComparingTo("14.0000");
47	        assertThat(r.withinLimits()).isTrue();
48	        assertThat(r.violations()).isEmpty();
49	    }
50	
51	    @Test
52	    void fuelMovesCgAndTowCgLandsExactlyOnSlopedEdge() {
53	        // 5000kg@690：TOW=60000，重心 (32.93m+3.45m)/60000 = 606.25in = 恰 15%MAC（斜边）。
