        assertThatThrownBy(() -> assemblyService.getActive(FLIGHT_ID))
                .isInstanceOf(NotFoundException.class);
        // 释放后编号可被其他航班占用
        assertThat(assemblyService.getOccupation("ULD001")).isEmpty();
